from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                _, write_time = cache[key]
                if t - write_time < ttl:
                    # still valid, but we are overwriting anyway
                    del cache[key]
                else:
                    # expired, treat as absent
                    del cache[key]
            if key not in cache and len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = [value, t]
            cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                value, write_time = cache[key]
                if t - write_time < ttl:
                    results.append(value)
                    cache.move_to_end(key)
                else:
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)
    return results

